class AgentsVersionsResource(SyncAPIResource):
    """Methods for agents versions."""

    def list(self, agent_id: str, *, request_options: RequestOptions | None = None) -> List[WorkflowVersionSummary]:
        """List the agent's published workflow versions.

        Newest first. Versions are immutable once published.

        ``GET /v1/agents/{id}/versions``
        """
        response = self._client._request("GET", f"/v1/agents/{path_param(agent_id)}/versions", options=request_options)
        return cast("List[WorkflowVersionSummary]", response["data"])

    def retrieve(
        self, agent_id: str, version: str, *, request_options: RequestOptions | None = None
    ) -> WorkflowVersion:
        """Get one published version, with what it runs.

        ``GET /v1/agents/{id}/versions/{v}``
        """
        return cast(
            "WorkflowVersion",
            self._client._request(
                "GET", f"/v1/agents/{path_param(agent_id)}/versions/{path_param(version)}", options=request_options
            ),
        )

    def diff(
        self, agent_id: str, a: str, b: str, *, request_options: RequestOptions | None = None
    ) -> WorkflowVersionDiff:
        """Compare two published versions.

        What changed from version `a` to version `b`: steps added, removed and changed
        (with each changed key, prompt text included), the flow, and the version's
        settings.

        ``GET /v1/agents/{id}/versions/{a}/diff/{b}``
        """
        return cast(
            "WorkflowVersionDiff",
            self._client._request(
                "GET",
                f"/v1/agents/{path_param(agent_id)}/versions/{path_param(a)}/diff/{path_param(b)}",
                options=request_options,
            ),
        )

    def restore(self, agent_id: str, version: str, *, request_options: RequestOptions | None = None) -> AgentDetail:
        """Roll back to a published version.

        Publishes version `v`'s content as a new version, changelog "Rolled back to
        v{v}", and moves the agent's deployments onto it. Old versions are never
        changed. The same checks as a publish apply: the graph is validated against
        today's rules (422 `invalid_workflow`), its calendars must still be connected,
        and an agent whose publish check blocks refuses it (409
        `publish_check_blocks_rollback`). 409 `version_live` when `v` is already live.
        The agent's prompt, greetings and voice aren't part of a version and don't
        change.

        ``POST /v1/agents/{id}/versions/{v}/restore``
        """
        return cast(
            "AgentDetail",
            self._client._request(
                "POST",
                f"/v1/agents/{path_param(agent_id)}/versions/{path_param(version)}/restore",
                options=request_options,
            ),
        )


